const CX={res:null,busy:false,w:null,id:0,msg:"",cond:{}};
function cxDefault(lv){const m=CXMETA[lv]; return {slots:m.ev?(state.nf?0:Math.min(8,m.slotsMax)):0, rb:Object.fromEntries(m.rb.map(a=>[a[0],0])), fl:{}, dev:{}, tp:{}, prb:0, sw:false, ms:false, human:0, sp:Object.fromEntries(m.sp.map(n=>[n,true])), must:Array(CXMUSTN).fill(""), own:{}};}
// 11/22 必ず含める品物の材料を末端までたどる。own にチェックした材料より下はたどらない。返り値: [[名前, 深さ, 品物1個あたりの数, 持っているか]]
function cxTree(it,own){const out=[]; (function go(k,d,mul){const ins=CXINS[k]; if(!ins) return; for(const [a,q] of Object.entries(ins)){const o=!!own[a]; out.push([a,d,mul*q,o]); if(!o) go(a,d+1,mul*q);}})(it,0,1); return out;}
function cxCond(){const lv=state.lv; if(!CX.cond[lv]) CX.cond[lv]=cxDefault(lv); return CX.cond[lv];}
function cxKey(){return state.lv+"|"+JSON.stringify(cxCond());}
// 11/25 ユーザー: その他の条件(施設を1台ずつ「なし〜最大Lv」、畑・森・鉱山は Lv ごとの数。環境設備の台数。発電ポールのLv。ツールパックのレシピ)
function cxFlU(c,a){ const v=(c.fl||{})[a[0]]; return Array.isArray(v)&&v.length===a[2]?v:Array(a[2]).fill(a[3]); }
function cxFlC(c,a){ const v=(c.fl||{})[a[0]], o={}; if(v&&!Array.isArray(v)) for(const [l,n] of Object.entries(v)) if(+l<a[3]&&n>0) o[l]=n; return o; }   // 11/25 ユーザー: 最大Lvは「残り全部」(ここには入れない)。0 は「なし」
function cxFlRest(a,cc){ return a[2]-Object.values(cc).reduce((x,y)=>x+y,0); }
function cxPoleU(c,m){ const v=(c.fl||{})["発電ポール"]; return Array.isArray(v)&&v.length===m.poleN?v:Array(m.poleN).fill(m.poleMax); }
function cxFlArr(c,m){ const o={}; for(const a of m.fl||[]){ if(a[1]==="u") o[a[0]]=cxFlU(c,a).slice(); else { const cc=cxFlC(c,a), r=[]; for(const [l,n] of Object.entries(cc)) for(let i=0;i<n;i++) r.push(+l); while(r.length<a[2]) r.push(a[3]); o[a[0]]=r; } } return o; }
function cxFlMax(c,m,f){ const a=(m.fl||[]).find(x=>x[0]===f); if(!a) return 99; return Math.max(0,...cxFlArr(c,m)[f]); }
function cxTpOff(c){ return Object.entries(c.tp||{}).filter(([k,v])=>v===false).map(([k])=>k); }
const CXOCCMIN={"2": 0, "3": 2, "4": 2, "5": 3, "6": 3, "7": 4, "8": 4, "9": 5, "10": 6, "11": 7, "12": 7, "13": 8, "14": 10, "15": 5, "16": 5, "17": 5, "18": 5, "19": 5, "20": 5, "21": 5};   // 11/27 初期の条件で組める占有アニモの最少(proto/dbg_occ.js)
function cxOccList(full){ return Array.from({length:Math.min(full-1,5)},(_,i)=>full-1-i).filter(n=>n>=Math.max(0,CXOCCMIN[state.lv]||0)); }
function cxHumLabel(v,pl){ const [a,b]=v.split(":"), sp=(f,r)=>`<span>${esc(f)}</span>(<span>${esc(r)}</span>)`; if(pl) return sp(a==="井"?"井戸":"鉱山",pl); if(v==="鉱山") return sp("鉱山","貝殻"); if(a==="井") return sp("井戸",b.startsWith("高速")?"高速レシピ・"+b.slice(2):b); return sp("鉱山",{"銅":"銅鉱石","石英":"石英鉱石","銀":"銀鉱石"}[b]||b); }   // 11/26 訳せるように施設名とレシピ名を分ける
function cxHums(c){ return [+c.human||0].concat((c.hum2||[]).map(x=>+x||0)); }   // 11/27 メインキャラ・サブキャラの時間
function cxHumSum(c){ return cxHums(c).reduce((a,b)=>a+b,0); }
// 11/27 計算結果(レシピごとの合計時間)を、キャラの時間に順に割り当てる(同じ施設に何人でも入れるので、順に詰めれば足りる)
function cxHumSplit(list,hs){ const out=hs.map(()=>[]), rest=hs.slice(); let k=0; for(const [v,h0,pl] of list.slice().sort((a,b)=>b[1]-a[1])){ let h=h0; while(h>0.05&&k<rest.length){ if(rest[k]<=0.05){k++;continue;} const t=Math.min(h,rest[k]); out[k].push([v,Math.round(t*10)/10,pl]); rest[k]-=t; h-=t; } } return out; }
// 訳せるように、1つずつ class 付きの span で区切る(日本語の地の文が混ざると行全体で訳そうとして訳せない)
function cxHumOut(list){ const c=cxCond(), hs=cxHums(c), one=x=>`<span class="hx">${cxHumLabel(x[0],x[2])} <span>1日約${x[1]}時間</span></span>`;
  if(!(c.hum2||[]).length) return list.map(one).join(" / ");
  const sp=cxHumSplit(list,hs); return hs.map((h,i)=>`<span class="hl"><span>キャラ${i+1}</span>: ${sp[i].length?sp[i].map(one).join(" / "):"<span>作業なし</span>"}</span>`).join(""); }
// 11/28 ユーザー: キャラが2人以上のときは、表の「キャラも作業」をどのキャラかに(キャラごとの割り当ては cxHumSplit と同じ)
function cxHumTag(r){ const one=`<span class="tag hum">キャラも作業</span>`; if(!state.cx||!r.humv||!CX.res||!CX.res.o||!CX.res.o.human) return one; const c=cxCond(); if(!(c.hum2||[]).length) return one;
  const sp=cxHumSplit(CX.res.o.human,cxHums(c)), who=sp.map((l,i)=>l.some(x=>x[0]===r.humv)?i+1:0).filter(Boolean);
  return who.length?who.map(i=>`<span class="tag hum">キャラ${i}も作業</span>`).join(""):one; }
function cxMoreChanged(c){ return (cxHumSum(c)>0)||Object.keys(c.fl||{}).length>0||Object.keys(c.dev||{}).length>0||cxTpOff(c).length>0||Object.values(c.sp||{}).some(v=>!v); }
function cxFlSetU(c,f,i,v){ const m=CXMETA[state.lv]; c.fl=c.fl||{}; let arr, a=(m.fl||[]).find(x=>x[0]===f);
  if(f==="発電ポール"){ arr=cxPoleU(c,m).slice(); arr[i]=v; if(arr.every(l=>l===m.poleMax)) delete c.fl[f]; else c.fl[f]=arr; return; }
  if(!a) return; arr=cxFlU(c,a).slice(); arr[i]=v; if(arr.every(l=>l===a[3])) delete c.fl[f]; else c.fl[f]=arr; }
function cxFlSetC(c,f,l,t){ const m=CXMETA[state.lv], a=(m.fl||[]).find(x=>x[0]===f); if(!a) return; c.fl=c.fl||{};
  const cc=Object.assign({},cxFlC(c,a)); let v=Math.max(0,Math.floor(+t.value||0)); v=Math.min(v,(cc[l]||0)+cxFlRest(a,cc)); if(v) cc[l]=v; else delete cc[l];   // 増やした分は最大Lv(残り)から
  if(!Object.keys(cc).length) delete c.fl[f]; else c.fl[f]=cc; }
const MXT=` <span class="tag mx">最大</span>`;
function subHr(p){ const h=p*24/100; return h<10?String(Math.max(0.1,Math.round(h*10)/10)):String(Math.round(h)); }
// 11/28 使う台が施設の台数より少ないとき(自分の条件で計算では、持っている台数)
function procUse(P){ const a=((CXMETA[state.lv]||{}).fl||[]).find(x=>x[0]===P.f&&x[1]==="u"); if(!a) return ""; let tot=a[2]; if(state.cx){ try{ tot=cxFlU(cxCond(),a).filter(l=>l>0).length; }catch(e){} }
  const used=P.gs.length; return used<tot?`<span class="sub" style="display:block;font-weight:400;font-size:.8rem;color:var(--muted);margin-top:2px">全${tot}台のうち${used}台を使います</span>`:""; }
function cxMoreUI(c,m){ const fl=m.fl||[]; if(!fl.length&&!m.sp.length&&!(m.tp||[]).length&&!m.hum) return "";
  const opt=(mx,cur)=>`<option value="0"${cur===0?" selected":""}>未購入</option>`+Array.from({length:mx},(_,i)=>mx-i).map(l=>`<option value="${l}"${cur===l?" selected":""}>Lv.${l}</option>`).join("");
  const row=a=>{ if(a[1]==="u") return `<div class="cxfl"><span class="cxfln">${esc(a[0])}${cxFlU(c,a).every(l=>l===a[3])?MXT:""}</span><span class="cxflv">${cxFlU(c,a).map((l,i)=>`<select data-cxflu="${esc(a[0])}" data-i="${i}" aria-label="${esc(a[0])}">${opt(a[3],l)}</select>`).join("")}</span></div>`;
    const cc=cxFlC(c,a), rest=cxFlRest(a,cc), sel=l=>`<select data-cxflc="${esc(a[0])}" data-lv="${l}">${Array.from({length:(cc[l]||0)+rest+1},(_,n)=>`<option value="${n}"${(cc[l]||0)===n?" selected":""}>${n}</option>`).join("")}</select>`;
    return `<div class="cxfl"><span class="cxfln"><span>${esc(a[0])}</span> <span class="foot">(<span>全部で${a[2]}</span>)</span>${Object.keys(cc).length?"":MXT}</span><span class="cxflv"><span class="cxflc">Lv.${a[3]} <span class="cxflauto" role="status" aria-label="自動" title="自動">${rest}</span></span>${Array.from({length:a[3]-1},(_,i)=>a[3]-1-i).map(l=>`<label class="cxflc">Lv.${l} ${sel(l)}</label>`).join("")}<label class="cxflc"><span>未購入</span> ${sel(0)}</label></span></div>`; };
  let h=`<details class="cxmore"${CX.openMore?" open":""}><summary><span>その他の条件</span> <span class="foot">(<span>施設のLv・環境設備など</span>)</span>${cxMoreChanged(c)?` <span class="tag swr">変更あり</span>`:` <span class="tag mx">すべて最大</span>`}</summary>`;
  if(fl.length){ h+=`<fieldset class="cxset"><legend>施設のLv</legend><p class="foot" style="margin:0 0 6px">ホームコインが足りず、まだ買っていない施設やLvを上げていない施設があるときに選びます。${IBH(`<span class="ibp">畑・森・鉱山はLvごとの数で、一番高いLvの数は、ほかのLvと「未購入」を選んだ残りが自動で入ります。ほかの施設は1台ずつのLvです。</span>`)}</p>`;
    h+=`<p class="cxflh">生産施設</p>`+fl.filter(a=>a[4]==="p").map(row).join("");
    if(m.poleFl) h+=`<div class="cxfl"><span class="cxfln">パチパチ発電ポール${cxPoleU(c,m).every(l=>l===m.poleMax)?MXT:""}</span><span class="cxflv">${cxPoleU(c,m).map((l,i)=>`<select data-cxflu="発電ポール" data-i="${i}" aria-label="パチパチ発電ポール">${opt(m.poleMax,l)}</select>`).join("")}</span></div>`;
    h+=`<p class="cxflh">加工施設</p>`+fl.filter(a=>a[4]==="k").map(row).join("")+`</fieldset>`; }
  if(m.dev.length) h+=`<fieldset class="cxset"><legend>環境設備</legend>${m.dev.map(([k,nm,n])=>{ const cur=(c.dev||{})[k]===undefined?n:+c.dev[k]; return `<label class="cxrow cxrbrow"><span>${esc(nm)}${cur===n?MXT:""}</span> <select data-cxdev="${k}">${Array.from({length:n+1},(_,i)=>n-i).map(v=>`<option value="${v}"${cur===v?" selected":""}>${v?v+"台":"未購入"}</option>`).join("")}</select></label>`; }).join("")}</fieldset>`;
  if(m.hum){ const hv=+c.human||0; h+=`<fieldset class="cxset"><legend>プレイヤーの放置作業</legend><p class="cxflh">1日に水汲み・採掘を放置できる時間</p><label class="cxrow cxrbrow"><span>キャラ1</span> <select id="cx-human">${[0,1,2,3,4,6,8,10,12,15,18,24].map(n=>`<option value="${n}"${hv===n?" selected":""}>${n?n+"時間":"しない"}</option>`).join("")}</select></label>${(c.hum2||[]).map((v,i)=>`<div class="cxrow cxrbrow hum2r"><span>キャラ${i+2}</span><span class="hum2c"><select data-hum2="${i}">${[1,2,3,4,6,8,10,12,15,18,24].map(n=>`<option value="${n}"${+v===n?" selected":""}>${n}時間</option>`).join("")}</select> <button type="button" class="hum2del" data-hum2del="${i}">外す</button></span></div>`).join("")}${(c.hum2||[]).length<4?`<button type="button" class="cxbtn2 hum2add" id="cx-hum2add">キャラを追加</button>`:""}<p class="foot" style="margin:0">寝ている間や出かけている間など、ゲームを起動したまま自分のキャラに井戸の水汲みや鉱山の採掘をさせておける時間です。${IBH(`<span class="ibp">キャラはアニモと一緒に作業します。どの井戸・鉱山で作業するのがいいかも計算します。</span><span class="ibp">ほかのキャラにも作業させるときは「キャラを追加」で、キャラごとの時間を選べます。同じ井戸・鉱山に何人でも入れる前提です。</span>`)}</p></fieldset>`; }   // 11/26 ユーザー
  if(m.sp.length||(m.tp||[]).length){ h+=`<fieldset class="cxset"><legend>解放しているレシピ${(cxTpOff(c).length||Object.values(c.sp||{}).some(v=>!v))?"":` <span class="tag mx">すべて解放</span>`}${IBH(`<span class="ibp">チェックを外したレシピは使わずに計算します。まだ解放していないレシピは外してください。</span>`)}</legend>`;
    if(m.sp.length) h+=`<p class="cxflh">レシピノートなどで解放するもの</p>`+m.sp.map(n=>`<label class="unlk"><input type="checkbox" data-cxsp="${esc(n)}"${c.sp[n]?" checked":""}> ${esc(n)}</label>`).join("");
    if((m.tp||[]).length) h+=`<p class="cxflh">改造ツールパック(モジュール)で解放するもの</p>`+m.tp.map(([n])=>`<label class="unlk"><input type="checkbox" data-cxtp="${esc(n)}"${(c.tp||{})[n]===false?"":" checked"}> ${esc(n)}</label>`).join("");
    h+=`</fieldset>`; }
  if(cxMoreChanged(c)) h+=`<button type="button" class="cxbtn2" id="cx-morereset">その他の条件を最初に戻す</button>`;
  return h+`</details>`; }
function cxProcOk(c,m,a){ if(cxTpOff(c).includes(a[0])) return false; return a[3]<=cxFlMax(c,m,a[1]); }   // 施設のLvで作れる加工品だけ「必ず含める」に出す
function cxPanel(){
  const lv=state.lv, m=CXMETA[lv], c=cxCond(), v=document.getElementById("view");
  let h=`<section class="area cx"><h2>自分の条件で計算</h2><p class="foot" style="margin:0 0 10px">条件を選んで「計算する」を押すと、この端末のブラウザで配置を計算します(数秒〜数十秒)。計算の仕方はおすすめの配置と同じですが、公開前の確認はしていないので目安として使ってください。</p>`;
  // 11/23 ユーザー: 「レシピの切り替え」は大事な選択なので、条件の一番上に枠つきで出す(ボタンにするほどではない)
  h+=`<fieldset class="cxset"><legend>レシピの切り替え${IBH((()=>{ const cur=c.sw?3:c.ms?(c.msOwn?2:1):0, rows=[["切り替えない","なし","基準","心配なし"],["時々切り替える","少し","多め","回し忘れはOK、止め忘れは注意"],["使い切りOKのサブだけ","少し","やや多め","心配なし"],["こまめに切り替える","多い","一番多い","注意"]];   // 11/26 ユーザー: 3つの違いが選ぶ前に分かるように
  return `<table class="cxswt"><thead><tr><th></th><th>手間</th><th>コイン</th><th>止め忘れ</th></tr></thead><tbody>${rows.map((r,i)=>`<tr${i===cur?' class="on"':""}>${r.map((x,k)=>k?`<td>${x}</td>`:`<th scope="row">${x}</th>`).join("")}</tr>`).join("")}</tbody></table>`; })())}</legend><label class="cxrow" style="margin:0"><select id="cx-sw"><option value="0"${c.sw||c.ms?"":" selected"}>切り替えない(セットしっぱなし)</option><option value="2"${!c.sw&&c.ms&&!c.msOwn?" selected":""}>時々切り替える(メイン＋サブ)</option><option value="3"${!c.sw&&c.ms&&c.msOwn?" selected":""}>使い切りOKのサブだけ(メイン＋サブ)</option><option value="1"${c.sw?" selected":""}>こまめに切り替える(コイン最大)</option></select></label><p class="foot" style="margin:6px 0 0">${c.sw?"加工施設のレシピを、1日の中で時間を分けて切り替える前提です。コインは増えますが、こまめに切り替える手間がかかります。":c.ms&&c.msOwn?"「時々切り替える」のうち、材料をほかのレシピで使わないサブだけにした配置です。サブは材料がたまったら使い切るまで回してメインに戻すだけなので、時間を気にしなくて済みます。コインは「時々切り替える」より少し減ることがあります。計算は少し長くかかります。":c.ms?"加工施設は1台ごとに、セットしっぱなしでいい「メイン」と、材料が余ったときに時々回す「サブ」(1台に1つまで)に分けます。サブを回さなくても、「切り替えない」の配置と同じになるだけで、材料を食い尽くすことはありません。":"加工施設は1台1レシピで、ずっと同じレシピのままにする前提です。手間はかかりませんが、切り替える場合よりコインが少なめになることがあります。"}</p>${c.sw?`<label class="cxrow" style="margin:8px 0 0">1台で切り替えるレシピ <select id="cx-swmax">${[0,2,3,4].map(n=>`<option value="${n}"${(+c.swMax||0)===n?" selected":""}>${n?n+"つまで":"制限なし"}</option>`).join("")}</select></label>`:""}</fieldset>`;   // 11/24 ユーザー: 1台あたりのレシピ数の上限
  { const full=(D[state.lv]&&D[state.lv].opts&&D[state.lv].opts[0]&&D[state.lv].opts[0].animo)||0;   // 11/24 ユーザー: 施設を減らす条件(占有アニモの上限)。おすすめの配置(全部入り)の体数から下げる
    if(c.occ!==undefined&&c.occ!==""&&!cxOccList(full).includes(+c.occ)) c.occ="";   // 11/27 選べない数(古い共有リンク・保存)は全部入りに
    if(full>1&&cxOccList(full).length) h+=`<label class="cxrow">アニモを占有する施設 <select id="cx-occ"><option value=""${c.occ?"":" selected"}>全部入り(${full}体)</option>${cxOccList(full).map(n=>`<option value="${n}"${+c.occ===n&&c.occ!==""?" selected":""}>${n}体まで(−${full-n}体)</option>`).join("")}</select></label><p class="foot" style="margin:-4px 0 10px">願い星をたくさん作りたいときなど、住宅エリアに回すアニモを増やしたい場合の選択肢です。${IBH(`<span class="ibp">体数を減らすと、その範囲でコインが一番多くなるように施設を選びます(全部入りは${full}体)。</span>`)}</p>`; }
  if(m.ev) h+=`<label class="cxrow"><span>イベント作物の枠数${IBH(`<span class="ibp">マジックカボチャ・追憶ランプの実を植える枠の合計です(2種類を半分ずつ)。8枠なら、デイリーで獲得できるイベント通貨で種代をまかなえます。</span>`)}</span> <select id="cx-slots">${Array.from({length:Math.floor(m.slotsMax/2)+1},(_,i)=>i*2).concat(m.slotsMax%2?[m.slotsMax]:[]).map(n=>`<option value="${n}"${c.slots===n?" selected":""}>${n?n+"枠":"なし(通常)"}</option>`).join("")}</select></label>`;
  if(m.rb.length||(m.poleMax>=5&&m.poleFl)) h+=`<fieldset class="cxset"><legend>持っている虹色フォームのアニモ${IBH(`<span class="ibp">虹色フォームは、ホーム能力がLv4のアニモです。施設に置くと、Lv3のアニモより作業が速くなります。</span>`)}</legend><p class="foot" style="margin:0 0 6px">施設に置ける数だけ選べます。どの施設に置くかは計算で決めます。</p>${m.rb.map(a=>`<label class="cxrow cxrbrow"><span>${a[4].map(n=>`<span>${esc(CXDISP[n]||n)}</span>`).join("・")}${a[4].length>1?` <span class="foot">(合計)</span>`:""} <span class="foot">(${a[3].map(f=>`<span>${esc(f[0])}</span>${f[1]?`(<span>${esc(f[1])}</span>)`:""}`).join("・")})</span></span> <select data-cxrb="${esc(a[0])}">${Array.from({length:a[2]+1},(_,n)=>`<option value="${n}"${(+c.rb[a[0]]||0)===n?" selected":""}>${n?n+"体":"なし"}</option>`).join("")}</select></label>`).join("")}${m.poleMax>=5&&m.poleFl?`<label class="cxrow cxrbrow"><span><span>雷のホーム能力Lv4のアニモ</span> <span class="foot">(<span>パチパチ発電ポール</span>)</span></span> <select id="cx-prb">${Array.from({length:m.poleN+1},(_,n)=>`<option value="${n}"${(c.prb===undefined?0:+c.prb)===n?" selected":""}>${n?n+"体":"なし"}</option>`).join("")}</select></label><p class="foot" style="margin:0 0 6px">発電ポールLv.5は、雷のホーム能力Lv4のアニモなら100%、Lv3なら85%の電力です。</p>`:""}</fieldset>`;
  // 11/23 ユーザー: ポールLv.5 は雷Lv4(虹色)の体数で選ぶ(雷Lv3 なら1本 85%=1,275W)  11/25 ユーザー: Lv はその他の条件へ、雷Lv4 の体数は虹色の欄へ
  h+=cxMoreUI(c,m);
  if(m.proc.length||m.raw.length){ const dn=n=>CXDISP[n]||n, sel=c.must.filter(Boolean);
    h+=`<fieldset class="cxset"><legend>必ず含める品物(5つまで)${IBH(`<span class="ibp">デイリーの注文で使う品物など、必ず作りたいものを選びます。</span><span class="ibp">それぞれ6時間で10個(1日40個)以上残る配置にします。</span>`)}</legend>`;
    if(sel.length<CXMUSTN) h+=`<div class="cxfind"><input type="search" id="cx-find" placeholder="品物の名前で探す(例: いちご、せっけん)" autocomplete="off" enterkeyhint="search"><div id="cx-hits" class="cxhits"></div></div>`;   // 11/24 ユーザー: 品物を探すのが大変なので検索(表記ゆれも)
    for(let q=0;q<CXMUSTN;q++){ if(q>0&&!c.must[q-1]&&!c.must[q]) break; const cur=c.must[q], used=new Set(sel.filter(x=>x!==cur));
      h+=`<label class="cxrow">${q+1}. <select data-cxmust="${q}"><option value="">なし</option><optgroup label="加工品">${m.proc.filter(a=>!used.has(a[0])&&(cur===a[0]||cxProcOk(c,m,a))).map(a=>`<option value="${esc(a[0])}"${cur===a[0]?" selected":""}>${esc(dn(a[0]))}</option>`).join("")}</optgroup><optgroup label="素材">${m.raw.filter(n=>!used.has(n)).map(n=>`<option value="${esc(n)}"${cur===n?" selected":""}>${esc(dn(n))}</option>`).join("")}</optgroup></select>${cur?`<button type="button" class="cxclr" data-cxclr="${q}" aria-label="選択を外す" title="選択を外す">×</button>`:""}</label>`; }
    if(sel.length){ h+=`<p class="foot" style="margin:0 0 8px">それぞれ6時間で10個(1日40個)以上残る配置にします。</p>`; if(!c.sw&&!c.ms) h+=`<p class="foot cxwarn" style="margin:0 0 8px">必ず含める品物があるときは、レシピの切り替えを「時々切り替える」か「こまめに切り替える」にするのがおすすめです。「切り替えない」だと、少しだけ作る品物のために加工の1台をまるごと使うので、コインの減り方が大きくなりやすいです。</p>`; }
    h+=`</fieldset>`;
    for(const it of sel){ const tr=cxTree(it,c.own[it]||{}); if(!tr.length) continue;
      h+=`<fieldset class="cxset"><legend><span>${esc(dn(it))}</span><span>: </span><span>もう持っている材料(作らなくていいもの)</span></legend>${tr.map(([k,d,mul,o])=>`<label class="unlk cxown" style="margin-left:${d*1.4}em"><input type="checkbox" data-cxown="${esc(k)}" data-cxit="${esc(it)}"${o?" checked":""}> ${esc(dn(k))}</label>`).join("")}</fieldset>`; } }
  h+=`<div class="cxgo"><button type="button" class="cxbtn cxbig" id="cx-go"${CX.busy?" disabled":""}>${CX.busy?"計算中…":"計算する"}</button><span class="cxmsg" role="status">${esc(CX.msg)}</span></div>${CX.why&&CX.why.length&&CX.key===cxKey()&&!CX.busy&&CX.why[0][2]==="sw"?`<div class="cxwhy"><p>必ず含める品物を作るには、1台の加工施設で2つ以上のレシピを回す必要があります。レシピの切り替えを「こまめに切り替える」にしてください。</p></div>`:CX.why&&CX.why.length&&CX.key===cxKey()&&!CX.busy?`<div class="cxwhy"><p>次の材料を、必ず含める品物とほかのレシピで取り合うため、レシピを切り替えずに回すと材料が足りなくなります。</p><ul class="cxwl">${CX.why.map(([k,its])=>`<li><b>${esc(cxDn(k))}</b>${its.length?`: ${its.map(x=>`<span>${esc(cxDn(x))}</span>`).join("<span>・</span>")}`:""}</li>`).join("")}</ul><p>${CX.why.every(w=>w[2]==="res")?"「もう持っている材料」でその材料にチェックを入れるか、品物を外すか、レシピの切り替えを「こまめに切り替える」にしてください。":"品物を外すか、レシピの切り替えを「こまめに切り替える」にしてください。"}</p></div>`:""}${cxSaveUI()}<div class="cxshare"><button type="button" class="cxbtn2" id="cx-share">この条件を共有(リンクをコピー)</button>${CX.shareMsg?`<span class="foot" role="status">${esc(CX.shareMsg)}</span>`:""}${CX.shareUrl?`<input class="cxshurl" readonly value="${esc(CX.shareUrl)}" aria-label="共有リンク">`:""}</div>${CX.res&&CX.res.key===cxKey()&&CX.res.o&&CX.res.o.lbCut?`<p class="foot" style="margin:8px 0 0">${CX.res.o.lbCut.wood?`<span>必ず含める品物を作るため、木材は最大より約${CX.res.o.lbCut.wood}%少なくなります。</span>`:""}${CX.res.o.lbCut.ore?`<span>必ず含める品物を作るため、鉱砂は最大より約${CX.res.o.lbCut.ore}%少なくなります。</span>`:""}</p>`:""}${CX.res&&CX.res.key===cxKey()&&CX.res.o&&(CX.res.o.human||[]).length?`<p class="foot cxhum" style="margin:8px 0 0"><b>プレイヤーの放置作業</b> ${cxHumOut(CX.res.o.human)}</p>`:""}${!c.sw&&c.ms&&CX.res&&CX.res.key===cxKey()?`<p class="foot" style="margin:8px 0 0">加工は線で区切ったまとまりが1台です。「メイン」はセットしっぱなしでOKのレシピです。「サブ・1日に約○時間まで」は、材料が余っているときに書いてある時間くらいだけ回し、終わったらメインに戻します(回しっぱなしにすると、ほかで使う材料まで使ってしまいます)。「サブ・材料を使い切ってOK」は、材料をほかのレシピで使わないので、たまった材料を使い切るまで回してからメインに戻せば大丈夫です。どちらも、サブを回している間はメインが止まります。サブを回さない日は、メインだけでも問題ありません。</p>`:""}${c.sw&&CX.res&&CX.res.key===cxKey()?`<p class="foot" style="margin:8px 0 0">加工の「時間の○%」は、その1台で各レシピを作る、1日のうちの時間の割合です(線で区切ったまとまりが1台)。合計が100%に足りない分は、レシピを外して止めておく時間です。止めずに回し続けると、ほかの施設で使う材料まで使ってしまいます。「セットしっぱなしでOK」の付いたレシピは、材料をほかで使わないので、止めずに回し続けても大丈夫です(多くできた分は売れます)。1日の割合を守れば、何時間ごとに切り替えても同じです。</p>`:""}${c.must.some(Boolean)&&CX.res&&CX.res.key===cxKey()?`<p class="foot" style="margin:8px 0 0">選んだ品物は、残す分(6時間で10個)も表の作る数に含めています。</p>`:""}${!CX.busy&&!(CX.res&&CX.res.key===cxKey())?`<div class="cxwait">条件を選んで「計算する」を押すと、ここに配置の表とアニモ編成が出ます。</div>`:""}${CX.busy?`<div class="cxbusy" role="progressbar" aria-label="計算中"><div style="flex:1;min-width:0"><b>配置を計算しています</b><div class="cxbar"><i style="width:${cxPct()}%"></i></div><span class="cxtime">約${cxPct()}%・${cxElapsed()}</span><br><span class="foot">%は目安です(条件によって計算にかかる時間が変わります)。</span></div></div>`:""}</section>`;
  v.insertAdjacentHTML("afterbegin",h);
}
function cxElapsed(){const t=Math.floor((Date.now()-(CX.t0||Date.now()))/1000); return `${t}秒経過`;}
function cxPct(){return Math.max(1,Math.min(99,Math.round((CX.p||0)*100)));}
function cxTick(){const el=document.querySelector(".cxtime"); if(el) el.outerHTML=`<span class="cxtime">約${cxPct()}%・${cxElapsed()}</span>`; const b=document.querySelector(".cxbar i"); if(b) b.style.width=cxPct()+"%";}   // 要素ごと差し替え(翻訳が効くように)
function cxToggle(){document.getElementById("view").insertAdjacentHTML("afterbegin",`<div class="ibrow" style="margin:0 0 10px"><div class="seg altsw cxsw" role="group" aria-label="配置の出し方" style="margin:0 0 10px"><button type="button" data-cx="0" aria-pressed="${!state.cx}">おすすめの配置</button><button type="button" data-cx="1" aria-pressed="${!!state.cx}">自分の条件で計算</button></div>${IBH(`<span class="ibp"><b>おすすめの配置</b>:施設は全部そのLvの最大レベルで、レシピも全部解放している前提の配置です。</span><span class="ibp"><b>自分の条件で計算</b>:施設のLvや、持っている虹色フォームのアニモなど、自分の条件に合わせて計算します。</span>`)}</div>`);}
function cxRun(){
  const lv=state.lv, m=CXMETA[lv], c=cxCond(), key=cxKey();
  const cond={swMax:(c.sw&&+c.swMax)?+c.swMax:undefined, occMax:(c.occ!==undefined&&c.occ!=="")?+c.occ:undefined, slots:m.ev?c.slots:0, rb:{}, rbOwn:m.rb.map(a=>[+c.rb[a[0]]||0, a[1]]).filter(a=>a[0]>0), rbMinMine:0, noRecipe:[], noVarPrefix:[], sw:!!c.sw, ms:!c.sw&&!!c.ms, msOwn:!c.sw&&!!c.ms&&!!c.msOwn, human:cxHumSum(c), humN:Math.max(1,cxHums(c).filter(x=>x>0).length)};
  if(m.poleFl){ const on=cxPoleU(c,m).filter(l=>l>0), n5=on.filter(l=>l>=5).length, k=Math.min(c.prb===undefined?0:+c.prb, n5), W5=m.poleMax>=5?m.poleW:CXPOLEW[5];   // 11/25 ユーザー: 1本ずつのLv。Lv.5 は雷Lv4 の体数まで100%、残りは85%
    const W=on.filter(l=>l<5).reduce((s,l)=>s+CXPOLEW[l],0)+k*W5+(n5-k)*W5*0.85; cond.poleN=on.length; cond.poles=cxPoleU(c,m).slice(); cond.pole_w=on.length?W/on.length:m.poleW; cond.poleLv=on.length?Math.max(...on):m.poleMax; if(cond.poleLv>=5) cond.poleL4=k; }
  else if(m.poleMax){ cond.pole_w=m.poleW; cond.poleLv=m.poleMax; }
  if(m.fl&&m.fl.length){ cond.fl=cxFlArr(c,m); cond.dev=Object.fromEntries(m.dev.map(([k,nm,n])=>[k,(c.dev||{})[k]===undefined?n:+c.dev[k]])); }
  cond.noVar=[]; for(const [nm,vs] of m.tp||[]) if((c.tp||{})[nm]===false) cond.noVar.push(...vs);
  const ms=c.must.filter(Boolean); if(ms.length) cond.must=ms.map(it=>{const sum={}; for(const [k,d,mul,o] of cxTree(it,c.own[it]||{})) if(o) sum[k]=(sum[k]||0)+mul; return {item:it, perDay:40, owned:Object.entries(sum)};});
  if(cond.must) cond.resOff=[...new Set(cond.must.flatMap(x=>x.owned.map(o=>o[0])))];   // 11/24 ユーザー: 持っている材料は取り合いの余りを残さなくてよい
  for(const n of m.sp) if(!c.sp[n]){const k=CXSP[n]; if(k==="作") cond.noRecipe.push(n); else cond.noVarPrefix.push(k);}
  if(!CX.w){ try{ CX.w=new Worker("calc/worker.js?v=c49e3aaca5"); }catch(e){ CX.msg="この画面では計算できません(ブラウザが対応していません)。"; render(); return; }
    CX.w.onmessage=e=>{const d=e.data; if(d.id!==CX.id) return;
      if(d.type==="step"){CX.n=d.n; if(d.p!==undefined) CX.p=Math.max(CX.p||0,d.p); cxTick(); return;}
      if(d.type==="final"){CX.res={key:CX.key,o:d.o,final:true}; CX.busy=false; clearInterval(CX.tm); CX.msg=`計算が終わりました(${(d.ms/1000).toFixed(1)}秒)。`; render(); return;}
      CX.busy=false; clearInterval(CX.tm); CX.why=d.type==="none"?(d.why||[]):[]; CX.msg=(d.type==="none"&&d.occMin)?`この条件では配置が組めませんでした。この条件なら、占有アニモは${d.occMin}体から組めます。`:d.type==="none"?(cxCond().occ!==undefined&&cxCond().occ!==""&&!(d.why||[]).length?"この条件では配置が組めませんでした。占有アニモの上限を増やしてください。":(CXMETA[state.lv].ev&&cxCond().slots>0&&(cxCond().dev||{}).lamp===0)?"イベント作物には日光ランプが要ります。日光ランプを置くか、イベント作物の枠を「なし」にしてください。":cxMoreChanged(cxCond())?"この条件では配置が組めませんでした。その他の条件で施設を減らしすぎていないか確かめてください(食料を作る畑なども要ります)。":"この条件では配置が組めませんでした。条件を変えてください。"):"計算できませんでした: "+d.err; render();};
    CX.w.onerror=e=>{CX.busy=false; clearInterval(CX.tm); CX.msg="計算できませんでした(計算の部品を読み込めません)。"; render();}; }
  CX.id++; CX.key=key; CX.busy=true; CX.res=null; CX.msg=""; CX.why=[]; CX.t0=Date.now(); CX.n=0; CX.p=0; clearInterval(CX.tm);
  CX.tm=setInterval(()=>{cxTick();},1000); render();
  CX.w.postMessage({id:CX.id, lv:+lv, cond});
}
function cxDn(n){return CXDISP[n]||n;}
// 11/24 ユーザー: 計算結果を5つまで保存して、あとで見比べる(この端末のブラウザに保存)
const CXSAVEN=5;
function cxSaved(){ try{ const a=JSON.parse(localStorage.getItem("aniimo-cxsave")||"[]"); return Array.isArray(a)?a:[]; }catch(e){ return []; } }
function cxSaveSet(a){ try{ localStorage.setItem("aniimo-cxsave",JSON.stringify(a)); return true; }catch(e){ return false; } }
function cxSum(lv,c){ const m=CXMETA[lv]||{}, p=[], S=t=>`<span>${t}</span>`; p.push(S(!c.sw&&c.ms?(c.msOwn?"使い切りOKのサブだけ":"時々切り替える"):c.sw?(+c.swMax?`こまめに切り替える(1台${c.swMax}つまで)`:"こまめに切り替える"):"切り替えない")); if(m.ev) p.push(S(c.slots?`イベント作物${c.slots}枠`:"イベント作物なし"));
  const rb=Object.values(c.rb||{}).reduce((a,b)=>a+(+b||0),0); p.push(S(rb?`虹色${rb}体`:"虹色なし")); if(c.occ!==undefined&&c.occ!=="") p.push(S(`占有${c.occ}体まで`));
  if(cxHumSum(c)>0) p.push(S((c.hum2||[]).length?`放置作業${cxHums(c).filter(x=>x>0).length}人・計${cxHumSum(c)}時間`:`放置作業${+c.human}時間`)); if(Object.keys(c.fl||{}).length) p.push(S("施設のLvを変更")); if(Object.keys(c.dev||{}).length) p.push(S("環境設備を変更")); if(m.poleMax>=5&&m.poleFl&&+c.prb>0) p.push(S(`雷Lv4のアニモ${+c.prb}体`));
  const tpo=cxTpOff(c); if(tpo.length) p.push(S("ツールパック未解放")+":"+tpo.map(x=>S(esc(x))).join("・"));
  const off=Object.entries(c.sp||{}).filter(([k,v])=>!v).map(([k])=>k); if(off.length) p.push(S("未解放")+":"+off.map(x=>S(esc(x))).join("・"));
  const ms=(c.must||[]).filter(Boolean); if(ms.length) p.push(S("必ず含める")+":"+ms.map(x=>S(esc(cxDn(x)))).join("・"));
  return p.join(" / "); }
function cxSaveUI(){ const a=cxSaved(), cur=CX.res&&CX.res.key===cxKey()&&!CX.busy; let h="";
  if(cur){ const done=a.some(x=>x.key===CX.res.key); h+=`<div class="cxsave">${done?`<span class="foot">この結果は保存済みです。</span>`:a.length>=CXSAVEN?`<span class="foot">保存は${CXSAVEN}件までです。下の一覧から消すと保存できます。</span>`:`<button type="button" class="cxbtn2" id="cx-save">この結果を保存して、あとで見比べる</button>`}</div>`; }
  if(a.length){ const best={}; for(const x of a) best[x.lv]=Math.max(best[x.lv]||0,x.o.coin||0);
    h+=`<details class="cxsaved"${CX.openSaved===false?"":" open"}><summary>保存した結果(${a.length}/${CXSAVEN})</summary><div class="tbl"><table><tr><th>Lv</th><th>コイン/日</th><th>占有アニモ</th><th>条件</th></tr>${a.map((x,i)=>`<tr${CX.res&&CX.res.key===x.key&&state.lv===x.lv?' class="cxnow"':""}><td>Lv.${esc(x.lv)}</td><td class="num"><b>約${Math.round(x.o.coin*1440/10000).toLocaleString()}万</b>${x.o.coin<best[x.lv]?`<br><span class="foot"><span>最大より</span> ${((x.o.coin/best[x.lv]-1)*100).toFixed(1)}%</span>`:""}</td><td class="num">${x.o.animo}体</td><td class="cxcond">${cxSum(x.lv,x.cond)}<br><span class="foot">${(d=>`${d.getMonth()+1}/${d.getDate()} ${d.getHours()}:${String(d.getMinutes()).padStart(2,"0")}`)(new Date(x.t))}</span><div class="cxsvb"><button type="button" class="cxbtn2" data-cxshow="${i}">表示</button><button type="button" class="cxbtn2 cxdel" data-cxdel="${i}">削除</button></div></td></tr>`).join("")}</table></div><p class="foot" style="margin:6px 14px 10px">保存はこの端末のブラウザだけに残ります。「表示」を押すと、その条件と結果に切り替わります。</p></details>`; }
  return h; }
document.getElementById("view").addEventListener("click",e=>{
  if(e.target.id==="cx-save"&&CX.res){ const a=cxSaved(); if(a.length>=CXSAVEN) return; a.push({t:Date.now(),lv:state.lv,cond:JSON.parse(JSON.stringify(cxCond())),key:CX.res.key,o:CX.res.o}); if(!cxSaveSet(a)) CX.msg="保存できませんでした(ブラウザの保存領域がいっぱいか、使えない設定です)。"; CX.openSaved=true; render(); return; }
  const sh=e.target.closest("[data-cxshow]"); if(sh){ const x=cxSaved()[+sh.dataset.cxshow]; if(!x) return; cxStop(); state.lv=x.lv; CX.cond[x.lv]=JSON.parse(JSON.stringify(x.cond)); CX.res={key:cxKey(),o:x.o,final:true}; CX.msg=""; CX.why=[]; CX.openSaved=true; const y0=(document.querySelector(".cxsaved")||sh).getBoundingClientRect().top; render(); const el=document.querySelector(".cxsaved"); if(el) window.scrollBy(0,el.getBoundingClientRect().top-y0); return; }   // 11/24 ユーザー: 表示で一番上に戻らない(保存した結果の一覧を同じ位置に残す)
  const dl=e.target.closest("[data-cxdel]"); if(dl){ const a=cxSaved(); a.splice(+dl.dataset.cxdel,1); cxSaveSet(a); CX.openSaved=true; render(); return; }
});
document.getElementById("view").addEventListener("toggle",e=>{ if(e.target.classList&&e.target.classList.contains("cxsaved")) CX.openSaved=e.target.open; if(e.target.classList&&e.target.classList.contains("cxmore")) CX.openMore=e.target.open; },true);
document.getElementById("view").addEventListener("click",e=>{ if(e.target.id!=="cx-morereset") return; const c=cxCond(), m=CXMETA[state.lv]; c.fl={}; c.dev={}; c.tp={}; c.sp=Object.fromEntries(m.sp.map(n=>[n,true])); CX.shareMsg=""; render(); });
function cxStop(){ if(!CX.busy) return; try{CX.w.terminate();}catch(e){} CX.w=null; CX.busy=false; clearInterval(CX.tm); CX.msg="条件が変わったので計算を止めました。「計算する」でやり直してください。"; }
// 11/25 ユーザー: 選んだ条件をほかの人に共有するリンク(#cx=…)。開いた人の画面に条件が入り、計算は開いた人が押す
let CXSHARE=null; try{ const h=String(location.hash||""); if(h.startsWith("#cx=")){ const b=h.slice(4).replace(/-/g,"+").replace(/_/g,"/"); CXSHARE=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(b+"===".slice((b.length+3)%4)),ch=>ch.charCodeAt(0)))); } }catch(e){ CXSHARE=null; }
function cxShareUrl(){ const c=cxCond(), d=cxDefault(state.lv), o={}; for(const k in c){ if(k==="must"){ const m=c.must.filter(Boolean); if(m.length) o.must=m; continue; } if(k==="own"){ const w={}; for(const it in c.own){ const t={}; for(const x in c.own[it]) if(c.own[it][x]) t[x]=true; if(Object.keys(t).length) w[it]=t; } if(Object.keys(w).length) o.own=w; continue; } if(c[k]&&typeof c[k]==="object"){ const t={}; for(const x in c[k]) if(JSON.stringify(c[k][x])!==JSON.stringify((d[k]||{})[x])) t[x]=c[k][x]; if(Object.keys(t).length) o[k]=t; } else if(JSON.stringify(c[k])!==JSON.stringify(d[k])) o[k]=c[k]; }   // 初期値と同じものは入れない(リンクを短く)
  const js=JSON.stringify({v:1,lv:state.lv,c:o}), u=new TextEncoder().encode(js); let bin=""; for(const x of u) bin+=String.fromCharCode(x); return location.href.split("#")[0]+"#cx="+btoa(bin).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,""); }
function cxApplyShare(x){ try{ const lv=String(x&&x.lv); if(!x||x.v!==1||!CXMETA[lv]) return false; const m=CXMETA[lv], d=cxDefault(lv), c=x.c||{};
    for(const k of ["slots","swMax"]) if(Number.isFinite(c[k])) d[k]=c[k];
    if(Number.isFinite(c.human)) d.human=Math.max(0,Math.min(24,c.human));
    { const h2=Array.isArray(c.hum2)?c.hum2:(c.hum2&&typeof c.hum2==="object"?Object.keys(c.hum2).sort((a,b)=>a-b).map(k=>c.hum2[k]):null); if(h2&&h2.length) d.hum2=h2.slice(0,4).map(h=>Math.max(1,Math.min(24,Math.floor(+h)||8))); }
    for(const k of ["sw","ms","msOwn"]) if(typeof c[k]==="boolean") d[k]=c[k];
    if(Number.isFinite(c.prb)) d.prb=Math.max(0,Math.min(m.poleN||0,c.prb));
    if(c.tp) for(const [n] of m.tp||[]) if(c.tp[n]===false) d.tp[n]=false;
    if(c.dev) for(const [k,nm,n] of m.dev||[]) if(Number.isFinite(c.dev[k])) d.dev[k]=Math.max(0,Math.min(n,c.dev[k]));
    if(c.fl&&typeof c.fl==="object"){ for(const a of m.fl||[]){ const v=c.fl[a[0]]; if(v===undefined) continue;
        if(a[1]==="u"&&Array.isArray(v)&&v.length===a[2]) d.fl[a[0]]=v.map(l=>Math.max(0,Math.min(a[3],Math.floor(+l)||0)));
        if(a[1]==="c"&&v&&!Array.isArray(v)){ const o={}; let t=0; for(const [l,n] of Object.entries(v)){ const L=+l, N=Math.floor(+n)||0; if(L>=0&&L<a[3]&&N>0&&t+N<=a[2]){ o[L]=N; t+=N; } } d.fl[a[0]]=o; } }
      const pv=c.fl["発電ポール"]; if(m.poleFl&&Array.isArray(pv)&&pv.length===m.poleN) d.fl["発電ポール"]=pv.map(l=>Math.max(0,Math.min(m.poleMax,Math.floor(+l)||0))); }
    for(const k of ["occ"]) if(typeof c[k]==="string") d[k]=c[k];
    if(c.rb) for(const k in d.rb) if(Number.isFinite(c.rb[k])) d.rb[k]=c.rb[k];
    if(c.sp) for(const k in d.sp) if(typeof c.sp[k]==="boolean") d.sp[k]=c.sp[k];
    const ok=new Set([...m.proc.map(a=>a[0]),...m.raw]), ms=Array.isArray(c.must)?[...new Set(c.must.filter(n=>ok.has(n)))].slice(0,CXMUSTN):[];
    d.must=ms.concat(Array(CXMUSTN).fill("")).slice(0,CXMUSTN);
    if(c.own) for(const it of ms) if(c.own[it]&&typeof c.own[it]==="object"){ d.own[it]={}; for(const k in c.own[it]) if(typeof c.own[it][k]==="boolean") d.own[it][k]=c.own[it][k]; }
    state.lv=lv; state.cx=true; CX.cond[lv]=d; CX.res=null; CX.why=[]; CX.msg="共有された条件を読み込みました。「計算する」を押すと配置が出ます。"; return true; }catch(e){ return false; } }
document.getElementById("view").addEventListener("click",e=>{ if(e.target.id!=="cx-share") return; const url=cxShareUrl(), done=()=>{ CX.shareMsg="リンクをコピーしました。送りたい人に貼り付けてください。"; CX.shareUrl=""; render(); }, fail=()=>{ CX.shareMsg="コピーできなかったので、下のリンクを長押し(右クリック)でコピーしてください。"; CX.shareUrl=url; render(); };
  try{ navigator.clipboard.writeText(url).then(done,fail); }catch(err){ fail(); } });
function render(){
  ibClose();
  if(CXSHARE){ const x=CXSHARE; CXSHARE=null; if(cxApplyShare(x)){ try{ history.replaceState(null,"",location.href.split("#")[0]); }catch(e){} } }
  if(CX.busy&&(!state.cx||cxKey()!==CX.key)) cxStop();   // 11/23 ユーザー: 計算中に条件を変えたら止める
  if(!state.cx){ render0(); cxToggle(); return; }
  const lv=state.lv, r=CX.res&&CX.res.key===cxKey()?CX.res.o:null;
  if(r){ const keep=D[lv], st={ms:state.ms,ev:state.ev,rbv:state.rbv,alt:state.alt,alt2:state.alt2,k:state.k,dl:state.dl,nf:state.nf}; state.nf=!(CXMETA[lv].ev&&cxCond().slots>0);
    D[lv]=Object.assign({},keep,{opts:[r],alt:undefined,alt2:undefined,ev6:undefined,ev8:undefined,ev16:undefined,rb:undefined,rbb:undefined,daily:undefined,ms:undefined,noFest:true});
    state.ms=false;state.ev=0;state.rbv="";state.alt=false;state.alt2=false;state.k=0;state.dl=false;
    try{ render0(); } finally { D[lv]=keep; Object.assign(state,st); }
    document.querySelectorAll("#view .cxhide").forEach(e=>e.remove());
  } else { document.getElementById("view").innerHTML=""; document.querySelectorAll("#seg-level button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.lv===state.lv)); }
  cxPanel(); cxToggle();
}
document.getElementById("view").addEventListener("click",e=>{const b=e.target.closest("[data-cx]"); if(b){state.cx=b.dataset.cx==="1"; render(); return;} const w=e.target.closest("[data-cxsw]"); if(w){cxCond().sw=w.dataset.cxsw==="1"; render(); return;} if(e.target.closest("#cx-go")) cxRun();});
